"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[4906],{2696:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>o,default:()=>c,frontMatter:()=>r,metadata:()=>i,toc:()=>h});var i=n(4565),s=n(4848),a=n(8453);const r={slug:"serenity-js-open-letter",title:"Open Letter to Jan Molak",tags:["testing","automation","serenity-js","hands-on","playwright"],image:"/img/serenity-js-social-card.jpg"},o=void 0,l={authorsImageUrls:[]},h=[{value:"Meeting People Where They Are",id:"meeting-people-where-they-are",level:2},{value:"A Shift in the Industry",id:"a-shift-in-the-industry",level:2},{value:"The Impact of AI on Testing",id:"the-impact-of-ai-on-testing",level:2},{value:"Why Serenity/JS Matters",id:"why-serenityjs-matters",level:2},{value:"Conclusion",id:"conclusion",level:2}];function d(e){const t={a:"a",h2:"h2",p:"p",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:"Jan,"}),"\n",(0,s.jsxs)(t.p,{children:["Your recent updates to ",(0,s.jsx)(t.a,{href:"https://serenity-js.org",children:"serenity-js.org"})," are a significant improvement, and they highlight something I believe is increasingly important for our industry: testing strategy matters more than tooling."]}),"\n",(0,s.jsx)(t.p,{children:"We've exchanged a few DMs about the accessibility of Serenity/JS, particularly how difficult it can be for newcomers to understand where it fits into their testing journey. When you asked me to review the latest changes to the website, I realised my feedback was about more than the site itself, so I thought I'd share it in the form of an open letter."}),"\n",(0,s.jsx)(t.h2,{id:"meeting-people-where-they-are",children:"Meeting People Where They Are"}),"\n",(0,s.jsx)(t.p,{children:"What stands out most about the updated site is how effectively it meets people where they are. Instead of assuming visitors already understand the Screenplay Pattern, it starts with the problems teams are trying to solve and then shows different paths into Serenity/JS."}),"\n",(0,s.jsx)(t.p,{children:"Whether someone is looking for better reporting, more maintainable tests, or a full Screenplay-based architecture, they can quickly understand where Serenity/JS fits and how it might help."}),"\n",(0,s.jsx)(t.p,{children:"That matters because most teams don't wake up looking for a new framework. They are looking for solutions to real problems. By focusing on those problems first, the site makes Serenity/JS far more approachable and relevant."}),"\n",(0,s.jsx)(t.h2,{id:"a-shift-in-the-industry",children:"A Shift in the Industry"}),"\n",(0,s.jsx)(t.p,{children:"Reviewing the site also reminded me of a broader shift happening across our industry."}),"\n",(0,s.jsx)(t.p,{children:"For years, conversations about test automation have centred on tools. Playwright versus Cypress. Selenium versus WebdriverIO. Page Objects versus Screenplay."}),"\n",(0,s.jsx)(t.p,{children:"Today, AI has become part of that conversation as well."}),"\n",(0,s.jsx)(t.p,{children:"And honestly, that's a good thing."}),"\n",(0,s.jsx)(t.p,{children:"AI is already helping teams write tests faster, understand systems more quickly, improve documentation, and eliminate repetitive work. Used well, it can make automation engineers dramatically more productive."}),"\n",(0,s.jsx)(t.p,{children:"Yet the rise of AI also reinforces an important truth: the value of testing has never been in writing code."}),"\n",(0,s.jsx)(t.p,{children:"The real value lies in understanding risk, identifying meaningful behaviours, and deciding what is worth testing in the first place."}),"\n",(0,s.jsx)(t.p,{children:"Those are fundamentally human skills."}),"\n",(0,s.jsx)(t.h2,{id:"the-impact-of-ai-on-testing",children:"The Impact of AI on Testing"}),"\n",(0,s.jsx)(t.p,{children:"An AI can generate a Playwright test in seconds. It can even generate hundreds of them. But someone still needs to decide which behaviours matter, what level of confidence is required, and how testing supports the goals of the business."}),"\n",(0,s.jsx)(t.p,{children:"As AI lowers the barrier to creating automation code, the differentiator will not be who can generate the most tests. It will be who can design the most effective testing strategy and communicate it clearly."}),"\n",(0,s.jsx)(t.p,{children:"This is why I believe test strategy should always come before tooling."}),"\n",(0,s.jsx)(t.p,{children:"Not because tools don't matter - they absolutely do."}),"\n",(0,s.jsx)(t.p,{children:"But the best tools amplify a good strategy rather than compensate for the lack of one."}),"\n",(0,s.jsx)(t.h2,{id:"why-serenityjs-matters",children:"Why Serenity/JS Matters"}),"\n",(0,s.jsx)(t.p,{children:"This is where I think Serenity/JS becomes particularly relevant."}),"\n",(0,s.jsx)(t.p,{children:"Its value isn't that it can automate a browser. Playwright already does that brilliantly."}),"\n",(0,s.jsx)(t.p,{children:"Its value is that it encourages teams to think about behaviour, intent, and outcomes. It helps automation express what users are trying to achieve rather than simply documenting which buttons were clicked."}),"\n",(0,s.jsx)(t.p,{children:"In an AI-assisted world, that emphasis on intent becomes even more important. When generating automation becomes easier, the quality of the thinking behind that automation becomes the real advantage."}),"\n",(0,s.jsx)(t.p,{children:"What I appreciate about the updated Serenity/JS website is that it moves the conversation in exactly that direction. It explains not only what Serenity/JS is, but also the problems it helps teams solve and the thinking behind it."}),"\n",(0,s.jsx)(t.p,{children:"The result is a much clearer path for newcomers and a stronger message for experienced practitioners."}),"\n",(0,s.jsx)(t.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,s.jsx)(t.p,{children:"In a world where AI is making test automation more accessible than ever, helping people think more clearly about testing may be one of the most valuable things a framework can do."}),"\n",(0,s.jsx)(t.p,{children:"Congratulations on the work."}),"\n",(0,s.jsx)(t.p,{children:"Best, Jan"})]})}function c(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453:(e,t,n)=>{n.d(t,{R:()=>r,x:()=>o});var i=n(6540);const s={},a=i.createContext(s);function r(e){const t=i.useContext(a);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(a.Provider,{value:t},e.children)}},4565:e=>{e.exports=JSON.parse('{"permalink":"/de/serenity-js-open-letter","source":"@site/blog/2026-06-04-serenity-js-open-letter.mdx","title":"Open Letter to Jan Molak","description":"Jan,","date":"2026-06-04T00:00:00.000Z","tags":[{"inline":true,"label":"testing","permalink":"/de/tags/testing"},{"inline":true,"label":"automation","permalink":"/de/tags/automation"},{"inline":true,"label":"serenity-js","permalink":"/de/tags/serenity-js"},{"inline":true,"label":"hands-on","permalink":"/de/tags/hands-on"},{"inline":true,"label":"playwright","permalink":"/de/tags/playwright"}],"readingTime":3.21,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"serenity-js-open-letter","title":"Open Letter to Jan Molak","tags":["testing","automation","serenity-js","hands-on","playwright"],"image":"/img/serenity-js-social-card.jpg"},"unlisted":false,"nextItem":{"title":"You Fired the Wrong Testers","permalink":"/de/fired-wrong-testers"}}')}}]);